"sql": "SELECT Customer.FirstName, Customer.LastName, SUM(Invoice.Total) AS TotalSpending FROM Customer JOIN Invoice ON Customer.CustomerId = Invoice.CustomerId GROUP BY Customer.CustomerId ORDER BY TotalSpending DESC LIMIT 5"
