"sql": "SELECT ar.Name AS ArtistName, COUNT(DISTINCT t.GenreId) AS DistinctGenres FROM Artist ar JOIN Album al ON ar.ArtistId = al.ArtistId JOIN Track t ON al.AlbumId = t.AlbumId GROUP BY ar.ArtistId, ar.Name HAVING COUNT(DISTINCT t.GenreId) > 3 ORDER BY DistinctGenres DESC"
}

